"""Materialize the runnable Kájovo Factory implementation.

Generated once from a tested source archive. Refuses unsafe zip paths.
"""
from __future__ import annotations
import base64, io, pathlib, zipfile

ARCHIVE = ""

root = pathlib.Path(__file__).resolve().parents[1]
raw = base64.b64decode(ARCHIVE)
with zipfile.ZipFile(io.BytesIO(raw)) as zf:
    for info in zf.infolist():
        target = (root / info.filename).resolve()
        if root.resolve() not in target.parents and target != root.resolve():
            raise SystemExit("unsafe archive path: " + info.filename)
        if info.is_dir():
            target.mkdir(parents=True, exist_ok=True)
            continue
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(zf.read(info.filename))
print("materialized", len(zf.infolist()), "files")
